import re
from bs4 import BeautifulSoup

# ==========================================
# 1. Parsing Logic (The Cleanup Crew)
# ==========================================

def clean_namu_html(raw_html, drop_folded=True):
    """
    Pre-processes Namuwiki HTML to make it LLM-friendly.
    
    Args:
        raw_html (str): The raw HTML content of a table/section.
        drop_folded (bool): If True, removes content inside collapsible sections (dl/dt/dd).
    
    Returns:
        str: The cleaned, simplified HTML structure.
    """
    soup = BeautifulSoup(raw_html, 'html.parser')

    # 0. Noise Removal: <noscript>
    # Namuwiki includes duplicate <img> tags inside <noscript> for fallback.
    # We must remove them to avoid double extraction (e.g., duplicated flags/logos).
    for noscript in soup.find_all('noscript'):
        noscript.decompose()

    # 1. Handle Images/Icons (Critical for flags and buttons)
    # Replaces <img alt="..."> with (icon: ...)
    for img in soup.find_all('img'):
        alt = img.get('alt', '')
        if not alt:
            continue
        marker = soup.new_string(f" (icon: {alt}) ")
        img.replace_with(marker)

    # 2. Handle Collapsible Content (<dl><dt><dd>)
    # Namuwiki uses <dl> for folding. 
    for dl in soup.find_all('dl'):
        # Check if it's actually a folding section (heuristic: contains "펼치기")
        dt = dl.find('dt')
        is_folding = dt and ('펼치기' in dt.get_text() or '접기' in dt.get_text())
        
        if is_folding:
            if drop_folded:
                # Option A: Delete the noise entirely
                dl.decompose()
            else:
                # Option B: Remove button, expose content
                if dt: dt.decompose()
                dd = dl.find('dd')
                if dd: dd.unwrap()
                dl.unwrap()
        else:
            # Not a folding section? Just unwrap it to be safe
            dl.unwrap()

    # 3. Handle Intra-Cell Stacked Data (<hr>, <br>)
    # Confirmed via Live Crawl: Member profiles use <br> and <hr> for separation.
    for hr in soup.find_all('hr'):
        hr.replace_with(soup.new_string(" | ")) # Visual separator -> Text separator
    
    for br in soup.find_all('br'):
        br.replace_with(soup.new_string("\n")) # Line break -> Newline

    # 4. Universal Tag Flattening
    # We only care about the Table Structure. Everything else is noise.
    allowed_tags = ['table', 'tr', 'td', 'th', 'tbody', 'thead']
    
    for tag in soup.find_all(True):
        if tag.name not in allowed_tags:
            tag.unwrap() # Removes the tag but keeps its text content

    # 5. Attribute Stripping
    # Remove clutter like 'class', 'style', 'data-dark-style'
    # Only keep structural attributes: rowspan, colspan
    for tag in soup.find_all(True):
        attrs = dict(tag.attrs)
        for attr in attrs:
            if attr not in ['rowspan', 'colspan']:
                del tag[attr]

    return soup.prettify()

# ==========================================
# 2. LLM Prompt Construction (Simulation)
# ==========================================

def get_markdown_prompt(cleaned_html):
    system_prompt = """
You are an expert Data Converter. Your goal is to convert HTML tables into the most optimal Markdown format for RAG (Retrieval Augmented Generation).
The HTML has been pre-cleaned. Analyze the data pattern and strictly follow these adaptive rules:

**1. Entity Card Pattern (e.g., Member Profiles)**
- **Detection**: Columns represent distinct entities (e.g., specific people), and rows contain their attributes (often stacked with `|` or `\\n`).
- **Action**: Convert to a **Card List** format.
- **Format**:
  ### Entity Name
  - Attribute: Value
  - Attribute: Value

**2. Key-Value Pattern (e.g., Infoboxes)**
- **Detection**: The first column contains headers/keys (e.g., "Debut", "Agency"), and subsequent columns contain values. Rowspans may group content.
- **Action**: Convert to a **Hierarchical List**.
- **Format**:
  - **Key**:
    - Value 1
    - Value 2 (e.g., if multiple items or icons exist)

**3. Uniform Data Pattern (e.g., Discography, Video Lists)**
- **Detection**: Standard clean rows with clear headers (e.g., "Date", "Title", "Link").
- **Action**: Maintain as a **Markdown Table**.

**General Rules**:
- Preserve icons like `(icon: ...)` as they provide vital context (e.g., Flags).
- Remove empty rows or cells that contain no meaningful info.
"""
    return f"System: {system_prompt}\n\nHuman: Convert this HTML:\n{cleaned_html}"

